def matrix_multiply(a, b):
    rows = len(a)
    cols = len(b[0])
    inner = len(b)
    result = [[0.0] * cols for _ in range(rows)]
    s = 0.0
    for i in range(rows):
        for j in range(cols):
            for k in range(inner):
                s += a[i][k] * b[k][j]
            result[i][j] = s
            s = 0.0
    return result

