def primes_up_to(n):
    if n < 2:
        return []
    sieve = [True] * (n // 2)
    sieve[0] = False
    for i in range(1, int((n + 1) / 2)):
        if sieve[i]:
            for j in range(i * 2, len(sieve), i):
                sieve[j] = False
    return [2] + [i * 2 + 1 for i, is_prime in enumerate(sieve) if is_prime]

